class Solution {
public:
    std::vector<std::vector<int>> modifiedGraphEdges(int n, std::vector<std::vector<int>>& edges, int source, int destination, int target) {
        auto run_dijkstra = [&]() -> long long {
            std::vector<std::vector<std::pair<int, int>>> adj(n);
            for (const auto& e : edges) {
                if (e[2] != -1) {
                    adj[e[0]].push_back({e[1], e[2]});
                    adj[e[1]].push_back({e[0], e[2]});
                }
            }
            std::vector<long long> dist(n, 1e18);
            dist[source] = 0;
            std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>, std::greater<>> pq;
            pq.push({0, source});
            while (!pq.empty()) {
                auto [d, u] = pq.top();
                pq.pop();
                if (d > dist[u]) continue;
                for (auto& [v, w] : adj[u]) {
                    if (dist[u] + w < dist[v]) {
                        dist[v] = dist[u] + w;
                        pq.push({dist[v], v});
                    }
                }
            }
            return dist[destination];
        };
        long long cur_dist = run_dijkstra();
        if (cur_dist < target) return {};
        bool matched = (cur_dist == target);
        for (auto& edge : edges) {
            if (edge[2] != -1) continue;
            if (matched) {
                edge[2] = 2000000000;
            } else {
                edge[2] = 1;
                cur_dist = run_dijkstra();
                if (cur_dist <= target) {
                    matched = true;
                    edge[2] += target - cur_dist;
                }
            }
        }
        return matched ? edges : std::vector<std::vector<int>>{};
    }
};

class Solution {
    public int[][] modifiedGraphEdges(int n, int[][] edges, int source, int destination, int target) {
        long curDist = runDijkstra(n, edges, source, destination);
        if (curDist < target) return new int[0][];
        boolean matched = (curDist == target);
        for (int[] edge : edges) {
            if (edge[2] != -1) continue;
            if (matched) {
                edge[2] = 2000000000;
            } else {
                edge[2] = 1;
                curDist = runDijkstra(n, edges, source, destination);
                if (curDist <= target) {
                    matched = true;
                    edge[2] += (int)(target - curDist);
                }
            }
        }
        return matched ? edges : new int[0][];
    }

    private long runDijkstra(int n, int[][] edges, int source, int destination) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            if (e[2] != -1) {
                adj.get(e[0]).add(new int[]{e[1], e[2]});
                adj.get(e[1]).add(new int[]{e[0], e[2]});
            }
        }
        long[] dist = new long[n];
        Arrays.fill(dist, (long)1e18);
        dist[source] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, source});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int)cur[1];
            if (d > dist[u]) continue;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new long[]{dist[v], v});
                }
            }
        }
        return dist[destination];
    }
}

var modifiedGraphEdges = function(n, edges, source, destination, target) {
    function runDijkstra() {
        const adj = Array.from({ length: n }, () => []);
        for (const [u, v, w] of edges) {
            if (w !== -1) {
                adj[u].push([v, w]);
                adj[v].push([u, w]);
            }
        }
        const dist = new Array(n).fill(Infinity);
        dist[source] = 0;
        const visited = new Set();
        for (let iter = 0; iter < n; iter++) {
            let u = -1;
            for (let i = 0; i < n; i++) {
                if (!visited.has(i) && (u === -1 || dist[i] < dist[u])) {
                    u = i;
                }
            }
            if (u === -1 || dist[u] === Infinity) break;
            visited.add(u);
            for (const [v, w] of adj[u]) {
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                }
            }
        }
        return dist[destination];
    }
    let curDist = runDijkstra();
    if (curDist < target) return [];
    let matched = (curDist === target);
    for (const edge of edges) {
        if (edge[2] !== -1) continue;
        if (matched) {
            edge[2] = 2000000000;
        } else {
            edge[2] = 1;
            curDist = runDijkstra();
            if (curDist <= target) {
                matched = true;
                edge[2] += target - curDist;
            }
        }
    }
    return matched ? edges : [];
};
